const req = $('Normalize Request').first().json;
const res = $input.first().json;
const hex = (n) => { let s = ''; for (let i = 0; i < n; i++) s += Math.floor(Math.random() * 16).toString(16); return s; };
const traceId = hex(32);
const rootId = hex(16);
const start = Number(req.startedAtMs) || Date.now();
const end = Date.now();
const ns = (ms) => String(Math.round(ms)) + '000000';
const str = (k, v) => ({ key: k, value: { stringValue: String(v ?? '') } });
const steps = Array.isArray(res.intermediateSteps) ? res.intermediateSteps : [];
const routed = steps.map(s => (s.action && s.action.tool) || 'unknown');
const common = [
  str('langfuse.trace.name', 'calendarmate-request'),
  str('langfuse.session.id', req.sessionId),
  str('langfuse.user.id', 'pm-user'),
  str('langfuse.environment', req.source === 'evaluation' ? 'evaluation' : 'production'),
  str('langfuse.trace.metadata.source', req.source),
  str('langfuse.trace.metadata.test_id', req.testId),
  str('langfuse.trace.metadata.routed_agents', routed.join(',') || 'none'),
  { key: 'langfuse.trace.tags', value: { arrayValue: { values: [{ stringValue: 'calendarmate' }, { stringValue: req.source }].concat(req.testId ? [{ stringValue: req.testId }] : []) } } },
];
const spans = [{
  traceId, spanId: rootId, name: 'CalendarMate Orchestrator', kind: 1,
  startTimeUnixNano: ns(start), endTimeUnixNano: ns(end),
  attributes: common.concat([
    str('langfuse.observation.type', 'agent'),
    str('langfuse.observation.input', req.chatInput),
    str('langfuse.observation.output', res.output),
    str('gen_ai.request.model', 'gpt-5-mini'),
  ]),
}];
const slice = steps.length ? (end - start) / steps.length : 0;
steps.forEach((s, i) => {
  spans.push({
    traceId, spanId: hex(16), parentSpanId: rootId,
    name: (s.action && s.action.tool) || 'tool', kind: 1,
    startTimeUnixNano: ns(start + i * slice), endTimeUnixNano: ns(start + (i + 1) * slice),
    attributes: common.concat([
      str('langfuse.observation.type', 'agent'),
      str('langfuse.observation.input', JSON.stringify((s.action && s.action.toolInput) || {})),
      str('langfuse.observation.output', typeof s.observation === 'string' ? s.observation : JSON.stringify(s.observation)),
    ]),
  });
});
const otlp = { resourceSpans: [{ resource: { attributes: [str('service.name', 'calendarmate-n8n')] }, scopeSpans: [{ scope: { name: 'n8n-calendarmate' }, spans }] }] };
return [{ json: { otlp, traceId, routedAgents: routed.join(',') || 'none', output: res.output, latencyMs: end - start } }];

const row = $('When running evaluation').first().json;
const out = String($('Format Response').first().json.output || '').toLowerCase();
const groups = String(row.must_contain_keywords || '').split(';').map(g => g.trim()).filter(Boolean);
const passedGroups = groups.filter(g => g.split('|').some(k => out.includes(k.trim().toLowerCase())));
const forbidden = String(row.forbidden_keywords || '').split('|').map(k => k.trim().toLowerCase()).filter(Boolean);
const violations = forbidden.filter(k => out.includes(k));
const coverage = groups.length ? passedGroups.length / groups.length : 1;
return [{ json: {
  keyword_coverage: Math.round(coverage * 100) / 100,
  no_forbidden_content: violations.length === 0 ? 1 : 0,
  test_pass: coverage === 1 && violations.length === 0 ? 1 : 0,
  missing_groups: groups.filter(g => !passedGroups.includes(g)).join(' ; '),
  violations: violations.join(', '),
} }];
